// ---- Utilitas Markdown (port dari seo_agent/common/markdown.py) ----
// Dipakai sama persis untuk konten internal & kompetitor agar outline H1-H3 apple-to-apple.
const RE_IMAGE = /!\[[^\]]*\]\([^)]*\)/g;
const RE_LINK = /\[([^\]]*)\]\((?:[^()]|\([^)]*\))*\)/g;
const RE_CITATION = /\[\[?\d{1,3}\]?\]/g;
const RE_BARE_URL_LINE = /^\s*(?:[-*]\s*)?<?https?:\/\/\S+>?\s*$/;
const RE_CHECKBOX_LINE = /^\s*[-*]\s*\[[ xX]\]\s/;
const RE_FENCE = /^\s{0,3}(```|~~~)/;
const RE_ATX = /^\s{0,3}(#{1,6})\s+(.+?)\s*#*\s*$/;
const RE_LIST_ITEM = /^\s*(?:[-*+]|\d+[.)])\s+(.*)$/;

function decodeEntities(s) {
  if (!s) return '';
  const named = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', hellip: '…', ndash: '–', mdash: '—', rsquo: '’', lsquo: '‘', rdquo: '”', ldquo: '“' };
  return String(s)
    .replace(/&#(\d+);/g, (_, d) => String.fromCodePoint(Number(d)))
    .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCodePoint(parseInt(h, 16)))
    .replace(/&([a-z]+);/gi, (m, n) => (named[n.toLowerCase()] ?? m));
}

function stripTags(html) {
  return decodeEntities(String(html || '').replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim();
}

function cleanHeadingText(text) {
  return text.replace(RE_IMAGE, '').replace(RE_LINK, '$1').replace(/[*_`]+/g, '').replace(/\\([\\`*_{}\[\]()#+\-.!])/g, '$1').replace(/\s+/g, ' ').trim();
}

function normalizeSetext(md) {
  const lines = md.split('\n');
  const out = [];
  let inFence = false;
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (RE_FENCE.test(line)) inFence = !inFence;
    const nxt = lines[i + 1];
    const isText = line.trim() && !/^[#\-*>|+]/.test(line.trimStart());
    if (!inFence && nxt !== undefined && isText) {
      if (/^\s{0,3}=+\s*$/.test(nxt)) { out.push('# ' + line.trim()); i++; continue; }
      if (/^\s{0,3}-{2,}\s*$/.test(nxt)) { out.push('## ' + line.trim()); i++; continue; }
    }
    out.push(line);
  }
  return out.join('\n');
}

function extractOutline(md, maxLevel = 3) {
  const outline = [];
  let inFence = false;
  for (const line of normalizeSetext(md).split('\n')) {
    if (RE_FENCE.test(line)) { inFence = !inFence; continue; }
    if (inFence) continue;
    const m = line.match(RE_ATX);
    if (m) {
      const level = m[1].length;
      const text = cleanHeadingText(m[2]);
      if (level <= maxLevel && text) outline.push([level, text]);
    }
  }
  return outline;
}

function formatOutline(outline, maxItems = 80) {
  if (!outline.length) return '(tidak ada heading terdeteksi)';
  const lines = outline.slice(0, maxItems).map(([l, t]) => `${'  '.repeat(l - 1)}H${l}: ${t}`);
  if (outline.length > maxItems) lines.push(`... (+${outline.length - maxItems} heading lainnya)`);
  return lines.join('\n');
}

function dropMenuLikeLists(lines, minRun = 12, maxWords = 4) {
  const out = [];
  let run = [];
  const flush = () => {
    const shortItems = run.filter((l) => RE_LIST_ITEM.test(l));
    if (shortItems.length < minRun) out.push(...run);
    run = [];
  };
  for (const line of lines) {
    const item = line.match(RE_LIST_ITEM);
    if (item && item[1].split(/\s+/).filter(Boolean).length <= maxWords) run.push(line);
    else if (!line.trim() && run.length) run.push(line);
    else { flush(); out.push(line); }
  }
  flush();
  return out;
}

function trimBeforeFirstH1(md) {
  const m = md.match(/^\s{0,3}#\s+\S/m);
  if (m && m.index > 0 && m.index < md.length * 0.5) return md.slice(m.index);
  return md;
}

function stripMarkdownNoise(md, { trimH1 = true } = {}) {
  md = normalizeSetext(md);
  if (trimH1) md = trimBeforeFirstH1(md);
  md = md.replace(RE_IMAGE, '').replace(RE_LINK, '$1').replace(RE_CITATION, '');
  let lines = md.split('\n').map((l) => l.replace(/\s+$/, ''))
    .filter((l) => !RE_BARE_URL_LINE.test(l) && !RE_CHECKBOX_LINE.test(l))
    .filter((l) => !['-', '*', '+'].includes(l.trim()));
  // Heading: buang **bold** di dalam heading ("## **Apa Itu X?**" -> "## Apa Itu X?")
  lines = lines.map((l) => { const m = l.match(RE_ATX); return m ? `${m[1]} ${cleanHeadingText(m[2])}` : l; });
  lines = dropMenuLikeLists(lines);
  return lines.join('\n').replace(/\n{3,}/g, '\n\n').trim();
}

function wordCount(text) {
  return (String(text).match(/[\p{L}\p{N}_]+/gu) || []).length;
}

function truncateMarkdown(md, maxChars) {
  if (md.length <= maxChars) return [md, false];
  let cut = md.lastIndexOf('\n\n', maxChars);
  if (cut < maxChars * 0.6) cut = maxChars;
  return [md.slice(0, cut).trimEnd(), true];
}
// ---- akhir utilitas ----
// Format satu halaman internal dengan struktur yang sama seperti [COMPETITOR_PAGE] (apple-to-apple).
const url = String($('Input dari agent').first().json.url || '').trim();
const row = $input.first().json || {};

if (!row.url) {
  return [{ json: { result: `ERROR: ${url} tidak ditemukan di knowledge base. Pastikan URL milik ${$env.SITE_DOMAIN} dan sudah di-index (jalankan workflow Ingestion), atau cari dulu dengan search_internal_content.` } }];
}

const md = row.markdown || '';
const outline = extractOutline(md);
const counts = { 1: 0, 2: 0, 3: 0 };
for (const [level] of outline) counts[level] += 1;
const [body, truncated] = truncateMarkdown(md, Number($env.SCRAPE_MAX_CHARS || 12000));

return [{ json: { result: [
  '[INTERNAL_PAGE]',
  `URL: ${row.url}`,
  `Title: ${row.title || '-'}`,
  `Meta description (excerpt): ${row.meta_description || '-'}`,
  `Word count: ${row.word_count ?? '-'}`,
  `Headings: H1=${counts[1]}, H2=${counts[2]}, H3=${counts[3]}`,
  `Terakhir diubah: ${row.modified_gmt || '-'} | di-index: ${row.indexed_at || '-'}`,
  '',
  'OUTLINE:',
  formatOutline(outline),
  '',
  `CONTENT (Markdown${truncated ? `, dipotong ke ${body.length} dari ${md.length} karakter` : ''}):`,
  body,
  '[/INTERNAL_PAGE]',
].join('\n') } }];
